import json
from pathlib import Path
rows=[]
def add(url,checked):rows.append(dict(url=url,checked=checked,scope='Relevant sections retrieved and read; not a full-document conformance audit.'))
for n,c in [(9868,'UDP surplus area/options and unchanged base header'),(896,'Interactive small-packet example and original inhibition rule'),(9438,'Cubic target, Reno-friendly region, beta and application-limited exclusions'),(3649,'Average-window relation and 83,333 segment / five-billion-packet example'),(9293,'Reset/half-close, window, segment and delayed-ACK requirements'),(5961,'Synchronized RST exact-sequence rules and SYN-SENT distinction'),(5681,'FlightSize threshold, repeated RTO, fast recovery and additive increase'),(6298,'RTO estimator ordering, floor/ceiling, Karn and timer restart'),(2018,'Block syntax/space, sender retention and receiver reneging'),(7323,'Window scale negotiation, exponent and unscaled SYN fields'),(8985,'TLP PTO calculation, one-probe constraint and timing guards'),(8290,'Flow hashing and nonabsolute isolation'),(9000,'Connection ID and migration requirements'),(6935,'Constrained IPv6 tunnel checksum exception')]:add(f'https://www.rfc-editor.org/rfc/rfc{n}.html',c)
for url,c in [('https://raw.githubusercontent.com/torvalds/linux/v6.12/net/ipv4/tcp_bbr.c','BBRv1 gains, full-bandwidth detection, ProbeRTT eligibility/timer/round'),('https://raw.githubusercontent.com/torvalds/linux/v6.12/include/net/tcp.h','TIMEWAIT_LEN60*HZ; RTO/delayed-ACK constants'),('https://raw.githubusercontent.com/torvalds/linux/v6.12/net/ipv4/syncookies.c','Cookie secrets/MSS and timestamp recovery of scale/SACK/ECN'),('https://datatracker.ietf.org/doc/html/draft-ietf-ccwg-bbr-06','Experimental ECN section: unspecified exact algorithm but CE response required'),('https://ee.lbl.gov/papers/congavoid.pdf','Original LBL/Berkeley1986 account and algorithm introduction'),('https://www.cs.utexas.edu/~lam/395t/papers/Mathis1998.pdf','Original paper Table1: periodic versus random loss and ACK-specific constants'),('https://man7.org/linux/man-pages/man7/tcp.7.html','CORK/QUICKACK semantics; tw_recycle through4.11; congestion options'),('https://man7.org/linux/man-pages/man2/listen.2.html','Linux backlog semantics and somaxconn4096 since5.4'),('https://man7.org/linux/man-pages/man7/socket.7.html','SO_RCVBUF doubling, reuse old/new options, REUSEPORT3.9 and UID'),('https://docs.python.org/3/library/socket.html','sendall failure cannot identify bytes sent; socket API overview'),('https://docs.python.org/3/library/asyncio-stream.html','drain watermark semantics and immediate-return scheduling caveat'),('https://pkg.go.dev/net','TCPConn.SetNoDelay default true'),('https://man7.org/linux/man-pages/man7/udp.7.html','PMTU EMSGSIZE and datagram truncation'),('https://www.dnsflagday.net/2020/','1232-byte recommendation'),('https://kernel.org/doc/html/latest/networking/ip-sysctl.html','SYN/SYNACK retry defaults, tcp_rmem defaults and configuration-dependent behavior')]:add(url,c)
Path('/tmp/audit-system-design/network03-sources.json').write_text(json.dumps(rows,indent=2)+'\n')
